// Shared terminal delivery step -- any sub-workflow that's done for this turn calls this
// instead of POSTing to Django itself, so the callback contract (and any future change to
// it) lives in exactly one place.
//
// root_execution_id (set once, in spine.json, before anything downstream is ever called)
// rides along here like any other context field and is passed straight through to Django.
// Django's n8n_callback handler is the one place that actually computes token usage: once
// this callback tells it the turn is done, it fires a background poll-then-walk of the
// whole execution tree (every nested Execute Workflow hop, chased via each call site's own
// metadata.subExecution.executionId) and sums whatever Chat Model usage it finds. That has
// to happen from outside n8n, after the fact -- from inside any single execution, the
// executions API only exposes runData once status is genuinely 'finished', and a node can
// never see that for its own still-running execution (confirmed against a live run under
// this deployment's EXECUTIONS_MODE=queue); and n8n's in-process $('NodeName') accessor
// can't reach a Chat Model node's output at all, since that only exists on the
// ai_languageModel connection type, not main (also confirmed live: 'No data found from
// main input'). Bringing usage tracking back required moving it out of n8n entirely.
const d = $json;
return [{ json: {
  group_name: d.group_name,
  session_id: d.session_id,
  text: d.message || '',
  type: (d.error && !['NO_MATCH', 'MULTIPLE_PROCESSES', 'AGENT_ERROR'].includes(d.error)) ? 'alert' : 'agent',
  ...(d._root_execution_id ? { root_execution_id: d._root_execution_id } : {}),
  state: {
    last_bot_message: d.message ?? null,
    intention_nodes: d.intention_nodes ?? {},
    active_node_id: d.active_node_id ?? null,
    reset_process: d.reset_process === true,
  },
  processes: d.processes ?? null,
} }];
